import '../../data/dto/batch_delete_result.dart'; import '../entities/competition.dart'; import '../repositories/competition_repository.dart'; class CompetitionUseCases { CompetitionUseCases(this.repository); final CompetitionRepository repository; Future<PagedCompetitionResult> list({int page=0,int size=20,CompetitionStatus? status,String? search})=>repository.list(page:page,size:size,status:status,search:search); Future<Competition> create({required String name,required String description})=>repository.create(name:name,description:description); Future<Competition> update({required String id,required String name,required String description})=>repository.update(id:id,name:name,description:description); Future<Competition> updateDefaults({required String id,required List<String> defaultDays,required List<String> defaultHours,required int defaultFieldCount})=>repository.updateDefaults(id:id,defaultDays:defaultDays,defaultHours:defaultHours,defaultFieldCount:defaultFieldCount); Future<Competition> activate(String id)=>repository.activate(id); Future<Competition> close(String id)=>repository.close(id); Future<Competition> duplicate(String id,String newName)=>repository.duplicate(id,newName); Future<void> delete(String id)=>repository.delete(id); Future<BatchDeleteResult> deleteMany(List<String> ids)=>repository.deleteMany(ids); }
